import { DEFAULT_OPTIONS } from './src/simulation/config.ts';
import { Simulation } from './src/simulation/world.ts';
import { BikeAIDriver } from './src/simulation/bike-ai.ts';
import { racingLineFor } from './src/simulation/racing-line.ts';
import { mod } from './src/core/math.ts';
for(const id of ['gpr1','gpr2'])for(const weather of ['clear','rain']){
 const sim=new Simulation({...DEFAULT_OPTIONS,mode:'practice',ruleset:'gp-motorcycle',circuit:'poggio-alto',weather,compound:weather==='rain'?'wet':'medium',opponents:0,vehicles:[id],seed:4417});sim.autoPlayer=true;sim.race.time=sim.race.greenAt+1;
 const b=sim.cars[0],start=sim.track.length-300;b.place(sim.track,start,racingLineFor(sim.track).offsetAt(start));b.dynamics.speed=b.speed=90;b.gear=6;b.rpm=15000;
 sim.ai[0]=new BikeAIDriver(b,.96,4417);
 let turn=null,apex=null;
 for(let i=0;i<60*120;i++){
  sim.step(1/120);const distance=mod(b.s-start,sim.track.length);
  if(distance>900&&turn===null)turn=b.speed;
  if(distance>950&&apex===null){apex=b.speed;break;}
 }
 console.log(JSON.stringify({id,weather,turn,apex,crashes:b.dynamics.crashes,lateral:b.lateral,inpit:b.inPit,pitreq:b.pitRequested,compound:b.tires[0].compound}));
}
